"""Commands added so the product works over the CLI and web app (generated by _tools/add_commands.py)."""

import contextlib
import io
import json
import pathlib
import tempfile
import unittest

from agent_ads.__main__ import main

EX = pathlib.Path(__file__).resolve().parent.parent / "examples"


class CommandTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, obj) -> str:
        path = pathlib.Path(self.tmp.name) / "req.json"
        path.write_text(json.dumps(obj), encoding="utf-8")
        return str(path)

    def run_cli(self, argv):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = main(argv)
        self.assertIn(code, (0, 1), out.getvalue())
        return json.loads(out.getvalue())

    def test_relevant_campaigns_win_with_disclosure(self):
        out = self.run_cli(["auction", str(EX / "campaigns.json"), "--query", "hotel in lisbon", "--intent", "hotel"])
        self.assertEqual([w["offer"] for w in out["sponsored"]], ["Harbor Lisbon", "Alfama Rooms"])
        self.assertTrue(out["disclosure"])

    def test_irrelevant_intent_gets_no_ads(self):
        out = self.run_cli(["auction", str(EX / "campaigns.json"), "--query", "pizza", "--intent", "food"])
        self.assertEqual(out["sponsored"], [])


if __name__ == "__main__":
    unittest.main()
